gsl.gsl_factorize.restype = ctypes.POINTER(ctypes.c_int)

def prime_factors(n):
    factors = []
    factor_array = gsl.gsl_factorize(n)
    for i in range(n):
        if factor_array[i] == 0:
            break
        factors.append(factor_array[i])
    return factors

def main(n):
    if n <= 0:
        return {'error': 'Input must be a positive integer.'}
    factors = prime_factors(n)
    return {'factors': factors, 'count': len(factors)}

if __name__ == '__main__':
    n = 60  # Example input
    result = main(n)
    print(result)

