class GSLVectorComplex(ctypes.Structure):
    _fields_ = [('size', ctypes.c_size_t), ('data', ctypes.POINTER(ctypes.c_double))]

class GSLEigenNonsymmWorkspace(ctypes.Structure):
    _fields_ = []


def create_gsl_matrix(matrix):
    rows = len(matrix)
    cols = len(matrix[0])
    gsl_matrix = GSLMatrix(rows, cols, (ctypes.c_double * (rows * cols))(*[item for sublist in matrix for item in sublist]))
    return gsl_matrix


def create_gsl_vector_complex(size):
    gsl_vector_complex = GSLVectorComplex(size, (ctypes.c_double * (2 * size))())
    return gsl_vector_complex


def compute_eigenvalues_nonsymm(gsl_matrix):
    size = gsl_matrix.size1
    workspace = GSLEigenNonsymmWorkspace()
    eigenvalues = create_gsl_vector_complex(size)
    gsl.gsl_eigen_nonsymm(gsl_matrix, ctypes.byref(eigenvalues), ctypes.byref(workspace))
    return [complex(eigenvalues.data[i], eigenvalues.data[i + 1]) for i in range(0, 2 * size, 2)]


def compute_eigenvalues(matrix):
    gsl_matrix = create_gsl_matrix(matrix)
    return compute_eigenvalues_nonsymm(gsl_matrix)

