class MedianAccumulator:
    def __init__(self, window_size):
        self.window_size = window_size
        self.data = (ctypes.c_double * window_size)()
        self.count = 0
        self.median = ctypes.c_double()
        self.gsl_median = gsl.gsl_stats_median

    def insert(self, value):
        if self.count < self.window_size:
            self.data[self.count] = value
            self.count += 1
        else:
            for i in range(1, self.window_size):
                self.data[i - 1] = self.data[i]
            self.data[self.window_size - 1] = value

    def compute_median(self):
        if self.count == self.window_size:
            self.median = self.gsl_median(self.data, 1, self.window_size)
            return self.median
        return None


def compute_moving_median(data, window_size):
    med_acc = MedianAccumulator(window_size)
    medians = []
    for i in range(len(data)):
        med_acc.insert(data[i])
        median = med_acc.compute_median()
        if median is not None:
            medians.append(median)
    return medians

