import numpy as np

# Load the GSL libraries
ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

# Define the GSL types
class GSLVector(ctypes.Structure):
    _fields_ = [("size", ctypes.c_size_t), ("data", ctypes.POINTER(ctypes.c_double))]

def numpy_to_gsl_matrix_complex(np_array):
    if not isinstance(np_array, np.ndarray) or np_array.dtype != np.complex:
        raise ValueError("Input must be a NumPy array of complex numbers.")
    rows, cols = np_array.shape
    gsl_matrix = gsl.gsl_matrix_complex_alloc(rows, cols)
    gsl_matrix.contents.data = np_array.ctypes.data
    return gsl_matrix

def gsl_vector_to_numpy(gsl_vector, size):
    return np.ctypeslib.as_array(gsl_vector.data, shape=(size,))

def compute_eigenvalues(A, B):
    if not (isinstance(A, np.ndarray) and isinstance(B, np.ndarray)):
        raise ValueError("Both A and B must be NumPy arrays.")
    if A.shape[0] != A.shape[1] or B.shape[0] != B.shape[1]:
        raise ValueError("Matrices A and B must be square.")
    if A.shape != B.shape:
        raise ValueError("Matrices A and B must have the same dimensions.")

    n = A.shape[0]
    gsl_A = numpy_to_gsl_matrix_complex(A)
    gsl_B = numpy_to_gsl_matrix_complex(B)

    eigenvalues = gsl.gsl_vector_alloc(n)
    eigenvectors = gsl.gsl_matrix_complex_alloc(n, n)

    result = gsl.gsl_eigen_genherm(gsl_A, gsl_B, eigenvalues, eigenvectors)
    if result != 0:
        raise RuntimeError("Error computing eigenvalues.")

    return gsl_vector_to_numpy(eigenvalues, n)

