class Permutation:
    def __init__(self, n):
        self.n = n
        self.perm = (ctypes.c_int * n)()
        self.index = (ctypes.c_int * n)()
        self.size = n
        self.factorial = self.factorial(n)

    def factorial(self, n):
        if n == 0:
            return 1
        result = 1
        for i in range(1, n + 1):
            result *= i
        return result

    def generate_permutations(self):
        result = []
        self._generate(0, result)
        return result

    def _generate(self, k, result):
        if k == self.size:
            result.append(list(self.perm))
        else:
            for i in range(k, self.size):
                self.perm[k], self.perm[i] = self.perm[i], self.perm[k]
                self._generate(k + 1, result)
                self.perm[k], self.perm[i] = self.perm[i], self.perm[k]

