        self.n = n
        self.perm = (ctypes.c_int * n)()
        self.init_permutation()

    def init_permutation(self):
        for i in range(self.n):
            self.perm[i] = i

    def generate_permutations(self):
        result = []
        self._generate_permutations(0, result)
        return result

    def _generate_permutations(self, index, result):
        if index == self.n:
            result.append(list(self.perm))
            return
        for i in range(index, self.n):
            self.perm[index], self.perm[i] = self.perm[i], self.perm[index]
            self._generate_permutations(index + 1, result)
            self.perm[index], self.perm[i] = self.perm[i], self.perm[index]

