class GSLRNG:
    def __init__(self, seed):
        self.rng_type = gsl_rng_knuthran2002()
        self.rng = gsl_rng_alloc(self.rng_type)
        gsl_rng_set(self.rng, seed)

    def generate_random_numbers(self, count):
        random_numbers = []
        for _ in range(count):
            random_numbers.append(gsl_rng_uniform(self.rng))
        return random_numbers

    def __del__(self):
        gsl_rng_free(self.rng)


def generate_random_numbers(seed, count):
    rng = GSLRNG(seed)
    return rng.generate_random_numbers(count)

