class GSL:
    def __init__(self):
        self.accel = gsl.gsl_interp_accel_alloc()
        self.interp_type = gsl.gsl_interp_cubic_spline

    def cubic_spline_interpolate(self, x_data, y_data, x_target):
        n = len(x_data)
        x_array = (ctypes.c_double * n)(*x_data)
        y_array = (ctypes.c_double * n)(*y_data)
        y_target = ctypes.c_double()

        gsl.gsl_interp_init(self.interp_type, x_array, y_array, n)
        y_target_value = gsl.gsl_interp_eval(self.interp_type, x_array, y_array, x_target, self.accel)
        return y_target_value

    def cleanup(self):
        gsl.gsl_interp_accel_free(self.accel)


def interpolate(x_data, y_data, x_target):
    gsl_instance = GSL()
    try:
        return gsl_instance.cubic_spline_interpolate(x_data, y_data, x_target)
    finally:
        gsl_instance.cleanup()

import ctypes

class GSLVector:
    def __init__(self, data):
        self.size = len(data)
        self.vector = self.create_gsl_vector(data)

    def create_gsl_vector(self, data):
        gsl = ctypes.CDLL('/usr/local/gsl/lib/libgsl.so')
        gsl.gsl_vector_alloc.restype = ctypes.c_void_p
        vector = gsl.gsl_vector_alloc(ctypes.c_size_t(self.size))
        gsl.gsl_vector_set.restype = None
        for i, value in enumerate(data):
            gsl.gsl_vector_set(vector, ctypes.c_size_t(i), ctypes.c_double(value))
        return vector

    def add(self, other):
        gsl = ctypes.CDLL('/usr/local/gsl/lib/libgsl.so')
        gsl.gsl_vector_add.argtypes = [ctypes.c_void_p, ctypes.c_void_p]
        gsl.gsl_vector_add(self.vector, other.vector)

    def to_list(self):
        gsl = ctypes.CDLL('/usr/local/gsl/lib/libgsl.so')
        result = []
        gsl.gsl_vector_get.restype = ctypes.c_double
        for i in range(self.size):
            result.append(gsl.gsl_vector_get(self.vector, ctypes.c_size_t(i)))
        return result


def load_gsl_libraries():
    ctypes.CDLL('/usr/local/gsl/lib/libgslcblas.so', mode=ctypes.RTLD_GLOBAL)
    return ctypes.CDLL('/usr/local/gsl/lib/libgsl.so')


def gsl_vector_add(vector_a_data, vector_b_data):
    load_gsl_libraries()
    vector_a = GSLVector(vector_a_data)
    vector_b = GSLVector(vector_b_data)
    vector_a.add(vector_b)
    return vector_a.to_list()


