import ctypes

class GSLVector:
    def __init__(self, size):
        self.size = size
        self.vector = ctypes.create_string_buffer(size * ctypes.sizeof(ctypes.c_double))
        self.ptr = ctypes.cast(self.vector, ctypes.POINTER(ctypes.c_double))

    def set(self, index, value):
        self.ptr[index] = value

    def get(self, index):
        return self.ptr[index]

class GSLMovStatWorkspace:
    def __init__(self, size):
        self.workspace = gsl.gsl_movstat_workspace_alloc(size)

    def free(self):
        gsl.gsl_movstat_workspace_free(self.workspace)

def compute_mad(input_data, end_type):
