        self.func = func
        self.c_func = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double)(self.call)

    def call(self, x):
        return self.func(x)

    def get_c_func(self):
        return self.c_func

def integrate(function, a, b):
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)

