    result = ctypes.c_double()
    resabs = ctypes.c_double()
    resasc = ctypes.c_double()

    gsl_func = GSLFunction(function)
    gsl_integration_qk21(gsl_func.get_c_func(), a, b, ctypes.byref(result), ctypes.byref(resabs), ctypes.byref(resasc))

