class GSLMatrix:
    def __init__(self, matrix):
        self.rows = len(matrix)
        self.cols = len(matrix[0]) if self.rows > 0 else 0
        self.data = (ctypes.c_double * (self.rows * self.cols))(*[item for sublist in matrix for item in sublist])

    def gsl_matrix(self):
        return self.data

def matrix_to_gsl(matrix):
    gsl_matrix = GSLMatrix(matrix)
    return gsl_matrix.gsl_matrix()

def gsl_matrix_to_numpy(gsl_matrix, rows, cols):
    return np.array(gsl_matrix).reshape((rows, cols)).tolist()

def compute_matrix_exponential(matrix, mode):
    if not matrix or not all(len(row) == len(matrix) for row in matrix):
        raise ValueError('Input must be a square matrix.')
    gsl_matrix = matrix_to_gsl(matrix)
    rows = len(matrix)
    cols = len(matrix[0])
    result_matrix = (ctypes.c_double * (rows * cols))()
    gsl = ctypes.CDLL('/usr/local/gsl/lib/libgslcblas.so', mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL('/usr/local/gsl/lib/libgsl.so')
    gsl.gsl_linalg_exponential_ss(gsl_matrix, result_matrix, mode)
    return gsl_matrix_to_numpy(result_matrix, rows, cols)

