if __name__ == '__main__':
    try:
        matrix = [[1, 2], [3, 4]]
        mode = 0
        result = compute_matrix_exponential(matrix, mode)
        print('Matrix Exponential:', result)
    except Exception as e:
        print('Error:', e)
    try:
        matrix = [[1, 2, 3], [4, 5, 6]]
        mode = 0
        result = compute_matrix_exponential(matrix, mode)
        print('Matrix Exponential:', result)
    except Exception as e:
        print('Error:', e)

import ctypes
import numpy as np

class GSLMatrix:
    def __init__(self, matrix):
        self.rows = len(matrix)
        self.cols = len(matrix[0]) if self.rows > 0 else 0
        self.data = (ctypes.c_double * (self.rows * self.cols))(*[item for sublist in matrix for item in sublist])

    def get_gsl_matrix(self):
        gsl_matrix = ctypes.cdll.gsl_matrix_alloc(self.rows, self.cols)
        ctypes.cdll.gsl_matrix_memcpy(gsl_matrix, ctypes.byref(self.data))
        return gsl_matrix

def matrix_to_gsl(matrix):
    return GSLMatrix(matrix).get_gsl_matrix()

def gsl_matrix_to_numpy(gsl_matrix):
    rows = ctypes.cdll.gsl_matrix_get(gsl_matrix, 0)
    cols = ctypes.cdll.gsl_matrix_get(gsl_matrix, 1)
    result = np.zeros((rows, cols))
    for i in range(rows):
        for j in range(cols):
            result[i, j] = ctypes.cdll.gsl_matrix_get(gsl_matrix, i, j)
    return result.tolist()

def compute_matrix_exponential(matrix, mode):
    if len(matrix) == 0 or len(matrix) != len(matrix[0]):
        raise ValueError('Input must be a square matrix.')
    gsl_matrix = matrix_to_gsl(matrix)
    exp_matrix = ctypes.cdll.gsl_matrix_alloc(len(matrix), len(matrix))
    result = ctypes.cdll.gsl_linalg_exponential_ss(gsl_matrix, exp_matrix, mode)
    if result != 0:
        raise RuntimeError('Error computing matrix exponential.')
    return gsl_matrix_to_numpy(exp_matrix)

