        gsl_matrix = ctypes.CDLL('/usr/local/gsl/lib/libgsl.so').gsl_matrix_alloc(self.rows, self.cols)
        ctypes.memmove(gsl_matrix.contents.data, self.data, self.rows * self.cols * ctypes.sizeof(ctypes.c_double))
        return gsl_matrix

def matrix_to_gsl(matrix):
