import ctypes
import numpy as np

class GSLMatrix:
    def __init__(self, rows, cols):
        self.rows = rows
        self.cols = cols
        self.matrix = np.zeros((rows, cols), dtype=np.float64)

    def fill(self, data):
        self.matrix = np.array(data, dtype=np.float64)

    def to_gsl(self):
        gsl_matrix = ctypes.cdll.gsl_matrix_alloc(self.rows, self.cols)
        for i in range(self.rows):
            for j in range(self.cols):
                ctypes.cdll.gsl_matrix_set(gsl_matrix, i, j, self.matrix[i, j])
        return gsl_matrix

    @staticmethod
    def gsl_matrix_to_numpy(gsl_matrix, rows, cols):
        result = np.zeros((rows, cols), dtype=np.float64)
        for i in range(rows):
            for j in range(cols):
                result[i, j] = ctypes.cdll.gsl_matrix_get(gsl_matrix, i, j)
        return result

def matrix_to_gsl(matrix):
    rows = len(matrix)
    cols = len(matrix[0]) if rows > 0 else 0
    gsl_matrix = GSLMatrix(rows, cols)
    gsl_matrix.fill(matrix)
    return gsl_matrix.to_gsl()

def compute_matrix_exponential(matrix, mode):
    rows = len(matrix)
    if rows == 0 or any(len(row) != rows for row in matrix):
        raise ValueError('Input must be a square matrix.')
    gsl_matrix = matrix_to_gsl(matrix)
    exp_matrix = GSLMatrix(rows, rows)
    exp_matrix_ptr = exp_matrix.to_gsl()
    status = ctypes.cdll.gsl_linalg_exponential_ss(gsl_matrix, exp_matrix_ptr, mode)
    if status != 0:
        raise RuntimeError('Error computing matrix exponential.')
    return GSLMatrix.gsl_matrix_to_numpy(exp_matrix_ptr, rows, rows)

if __name__ == '__main__':
    ctypes.CDLL('/usr/local/gsl/lib/libgslcblas.so', mode=ctypes.RTLD_GLOBAL)
    ctypes.cdll.gsl = ctypes.CDLL('/usr/local/gsl/lib/libgsl.so')

    # Test cases
    test_matrix = [[1, 2], [3, 4]]
    mode = 0
    try:
        result = compute_matrix_exponential(test_matrix, mode)
        print(result)
    except Exception as e:
        print(f'Error: {e}')

import ctypes

gslcblas = ctypes.CDLL('/usr/local/gsl/lib/libgslcblas.so', mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL('/usr/local/gsl/lib/libgsl.so')

class GSLSpMatrix:
    def __init__(self, n, m):
        self.matrix = gsl.gsl_spmatrix_alloc(n, m)

    def set_element(self, row, col, value):
        gsl.gsl_spmatrix_set(self.matrix, row, col, value)

    def get_elements(self):
        elements = []
        for i in range(self.matrix->size1):
            for j in range(self.matrix->size2):
                value = gsl.gsl_spmatrix_get(self.matrix, i, j)
                if value != 0:
                    elements.append((i, j, value))
        return elements

    def swap_elements(self, i, j):
        gsl.gsl_spmatrix_swap(self.matrix, i, j)

    def __del__(self):
        gsl.gsl_spmatrix_free(self.matrix)

# Example usage
if __name__ == '__main__':
    n, m = 5, 5
    sp_matrix = GSLSpMatrix(n, m)
    sp_matrix.set_element(1, 2, 3.5)
    sp_matrix.set_element(2, 1, 4.5)
    print('Before swap:', sp_matrix.get_elements())
    sp_matrix.swap_elements(1, 2)
    print('After swap:', sp_matrix.get_elements())

