    gsl.gsl_integration_qk61.restype = ctypes.c_int

    result = ctypes.c_double()
    error = ctypes.c_double()

    gsl_func = GSLFunction(func)
    status = gsl.gsl_integration_qk61(ctypes.byref(gsl_func.gsl_func), a, b, ctypes.byref(result), ctypes.byref(error))

    if status != 0:
        raise RuntimeError('Integration failed with status: {}'.format(status))

    integral_square = integrate_function(lambda x: func(x) ** 2, a, b)[0]

    return {
        'integral_result': result.value,
        'absolute_error': error.value,
        'absolute_value_of_integral': abs(result.value),
        'integral_of_square': integral_square
    }

