def func_wrapper(func):
    def wrapper(x):
        return func(x)
    return GSLFunction(ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double)(wrapper), None)

def chebyshev_coefficients(order, func, a, b):
    gsl_function = func_wrapper(func)
    coeffs_array = (ctypes.c_double * (order + 1))()
    gsl.gsl_cheb_series_alloc.restype = ctypes.POINTER(GSLChebSeries)
    cheb_series = gsl.gsl_cheb_series_alloc(order)
    gsl.gsl_cheb_series_init(cheb_series, a, b, gsl_function)
    gsl.gsl_cheb_series_coefficients(cheb_series, coeffs_array)
    coefficients = [coeffs_array[i] for i in range(order + 1)]
    gsl.gsl_cheb_series_free(cheb_series)
    return coefficients

