class RingBuf:
    def __init__(self, size):
        self.size = size
        self.buffer = ctypes.create_string_buffer(size * ctypes.sizeof(ctypes.c_int))
        self.head = 0
        self.tail = 0
        self.count = 0

    def initialize_ringbuf(self):
        self.head = 0
        self.tail = 0
        self.count = 0

    def insert_into_ringbuf(self, values):
        for value in values:
            if self.count < self.size:
                ctypes.memmove(ctypes.byref(self.buffer, self.head * ctypes.sizeof(ctypes.c_int)), ctypes.byref(ctypes.c_int(value)), ctypes.sizeof(ctypes.c_int))
                self.head = (self.head + 1) % self.size
                self.count += 1
            else:
                raise Exception('Ring buffer is full')

    def copy_ringbuf_to_list(self):
        result = []
        for i in range(self.count):
            index = (self.tail + i) % self.size
            result.append(ctypes.cast(ctypes.byref(self.buffer, index * ctypes.sizeof(ctypes.c_int)), ctypes.POINTER(ctypes.c_int)).contents.value)
        return result

