        gsl_matrix = ctypes.create_string_buffer(self.rows * self.cols * ctypes.sizeof(ctypes.c_double))
        np.copyto(np.frombuffer(gsl_matrix, dtype=np.float64).reshape((self.rows, self.cols)), self.matrix)
        return gsl_matrix

