import ctypes

def create_histogram2d(nx, ny, xrange, yrange):
    if not (isinstance(nx, int) and isinstance(ny, int)) or nx <= 0 or ny <= 0:
        raise ValueError('nx and ny must be positive integers')
    if not (isinstance(xrange, list) and isinstance(yrange, list)):
        raise ValueError('xrange and yrange must be lists')
    if len(xrange) < 2 or len(yrange) < 2:
        raise ValueError('xrange and yrange must contain at least two elements each')
    if not all(x < y for x, y in zip(xrange, xrange[1:])):
        raise ValueError('xrange must be in increasing order')
    if not all(x < y for x, y in zip(yrange, yrange[1:])):
        raise ValueError('yrange must be in increasing order')

    ctypes.CDLL('/usr/local/gsl/lib/libgslcblas.so', mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL('/usr/local/gsl/lib/libgsl.so')

    gsl_histogram2d_calloc_range = gsl.gsl_histogram2d_calloc_range
    gsl_histogram2d_calloc_range.argtypes = [ctypes.c_int, ctypes.c_int, ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double)]
    gsl_histogram2d_calloc_range.restype = ctypes.POINTER(ctypes.c_void_p)

    x_range_array = (ctypes.c_double * len(xrange))(*xrange)
    y_range_array = (ctypes.c_double * len(yrange))(*yrange)

    histogram_ptr = gsl_histogram2d_calloc_range(nx, ny, x_range_array, y_range_array)
    if not histogram_ptr:
        raise MemoryError('Failed to allocate memory for histogram')

    return histogram_ptr

